"use strict";

/**
 * Ambient NPC chatter: the overhead lines NPCs say on their own - ducks quacking, sheep, cows,
 * the Grand Exchange experts, town criers, the Goblin Village soldiers' "Red armour best!" - with
 * the spacing, animation and area sound live OSRS sends, from rsprox captures.
 *
 * Data: data/definitions/npc-captured-chatter.json, generated by `rsprox_index.py npc-says` in
 * osrs-captures (never edited by hand): per NPC its lines with weights, the gap between lines as
 * quantiles, an `order` when it keeps a fixed cycle, `phrases` it always says in order (the H.A.M.
 * deacon's sermon sentences) with their own `phraseGap`, and `fighting` when its lines go with a
 * fight.
 * A line's animation and area sound are its `seq`/`sound`, or one of its weighted `gestures` when
 * the NPC alternates them (a town crier rings his bell or scratches his head).
 * plugins/npcs/data/npc-chatter.json leaves out NPCs other code drives (bosses, minigames,
 * cutscenes) and lines that answer another player's theft or announce news that was not yet live.
 *
 * Only NPCs in an active region (one a real player is near) are scheduled: every DISCOVER_TICKS
 * the server's active NPCs are scanned for chatter NPCs, and each one found keeps its own next
 * tick. A new NPC's first line comes at a random point of one gap, so a field of sheep does not
 * bleat in unison. An NPC talking to or fighting a player, or dying, waits BUSY_RETRY_TICKS; one
 * whose lines go with a fight speaks only while it fights another NPC.
 * Docs: docs/npc-chatter.md.
 */
const fs = require("fs");
const path = require("path");
const SKIP = require(path.join(__dirname, "data", "npc-chatter.json"));
/** Every skipLines pattern, whatever its group. */
const SKIP_LINES = Object.values(SKIP.skipLines).flat();

const DATA_FILE = "npc-captured-chatter.json";
/** Ticks between scans of the active NPCs for chatter NPCs not yet scheduled. */
const DISCOVER_TICKS = 8;
/** The share of an NPC's sightings skipLines must leave for its captured gap to still hold. */
const KEPT_SHARE = 0.5;
/** Ticks a busy NPC waits before trying its line again. */
const BUSY_RETRY_TICKS = 5;
/** The quantiles npc-captured-chatter.json stores gaps at, as fractions. */
const GAP_QUANTILES = [0.05, 0.25, 0.5, 0.75, 0.95];

let core = null;
/** Npc id -> { lines, units, totalWeight, gap, phraseGap, order, fighting }. */
const chatterById = new Map();
/** Chatter NPCs currently scheduled. */
const live = new Set();
/**
 * NPC -> { next, index, phrase, at }: its next line's tick, its place in its cycle (ordered NPCs),
 * and the phrase it is in the middle of with the next fragment's place.
 */
const schedule = new WeakMap();
let nextDiscover = 0;
let random = Math.random;

function readDefinitions() {
  return JSON.parse(fs.readFileSync(path.join(core.GameConstants.DEFINITIONS_DIRECTORY, DATA_FILE), "utf8"));
}

/** A gameval's family: its name without a trailing number, as the extractor groups them. */
function familyOf(name) {
  return name.replace(/_?\d+$/, "");
}

/**
 * The excluded names, and their families: an NPC whose lines come from its family (`family`)
 * is excluded with any excluded member (the hangman armours, the H.A.M. buyers).
 */
function skippedNpcs() {
  const names = new Set(Object.values(SKIP.skipNpcs).flat());
  return { names, families: new Set([...names].map(familyOf)) };
}

function isSkipped(entry, skipped) {
  return skipped.names.has(entry.name) || (entry.family != null && skipped.families.has(entry.family));
}

function skippedLine(text) {
  const lower = text.toLowerCase();
  return SKIP_LINES.some((pattern) => lower.includes(pattern));
}

/**
 * One NPC's chatter from its generated entry, or null when nothing of it is left to say, or when
 * skipLines took most of what it said: its captured gap is then the spacing of the lines removed
 * (a Varrock guard's theft answers), not of what is left.
 */
function entryFor(entry) {
  const lines = entry.lines.filter((line) => !skippedLine(line.text));
  if (lines.length === 0) return null;
  const weightOf = (list) => list.reduce((sum, line) => sum + line.weight, 0);
  if (weightOf(lines) < KEPT_SHARE * weightOf(entry.lines)) return null;
  const kept = new Set(lines.map((line) => line.text));
  const byText = new Map(lines.map((line) => [line.text, line]));
  const order = entry.order?.every((text) => kept.has(text)) ? entry.order.map((text) => byText.get(text)) : null;
  // A phrase is said whole or not at all; its first line's weight picks it.
  const phrases = (entry.phrases ?? [])
    .filter((phrase) => phrase.every((text) => kept.has(text)))
    .map((phrase) => phrase.map((text) => byText.get(text)));
  const inPhrase = new Set(phrases.flat());
  const units = [
    ...phrases.map((phrase) => ({ weight: phrase[0].weight, phrase })),
    ...lines.filter((line) => !inPhrase.has(line)).map((line) => ({ weight: line.weight, phrase: [line] })),
  ];
  return {
    lines,
    units,
    totalWeight: units.reduce((sum, unit) => sum + unit.weight, 0),
    gap: entry.gap,
    phraseGap: entry.phraseGap ?? entry.gap,
    order,
    fighting: entry.fighting === true,
  };
}

function load(definitions) {
  chatterById.clear();
  const skipped = skippedNpcs();
  let missing = 0;
  for (const entry of Object.values(definitions.npcs)) {
    if (isSkipped(entry, skipped)) continue;
    const id = core.CacheDefinitions.getNpcId(entry.name);
    if (id == null) {
      missing++;
      continue;
    }
    const chatter = entryFor(entry);
    if (chatter) chatterById.set(id, chatter);
  }
  if (missing > 0) console.warn(`[NpcChatter] ${missing} NPCs from ${DATA_FILE} are not in the cache`);
}

function start(pluginApi) {
  core = pluginApi.core;
  load(readDefinitions());
  core.TaskManager.submit(new (class NpcChatterTask extends core.Task {
    constructor() {
      super(1, null, false);
    }
    execute() {
      tick(core.World.getProcessCycle());
    }
  })());
}

/** A gap in ticks, drawn by interpolating between the stored quantiles. */
function sampleGap(gap) {
  const u = random();
  let value;
  if (u <= GAP_QUANTILES[0]) value = gap[0];
  else if (u >= GAP_QUANTILES[GAP_QUANTILES.length - 1]) value = gap[gap.length - 1];
  else {
    let i = 1;
    while (u > GAP_QUANTILES[i]) i++;
    const span = (u - GAP_QUANTILES[i - 1]) / (GAP_QUANTILES[i] - GAP_QUANTILES[i - 1]);
    value = gap[i - 1] + span * (gap[i] - gap[i - 1]);
  }
  return Math.max(1, Math.round(value));
}

/** The NPC's next line: the next fragment of its phrase, the next of its cycle, or a new pick. */
function pickLine(chatter, state) {
  if (state.phrase) {
    const line = state.phrase[state.at++];
    if (state.at >= state.phrase.length) state.phrase = null;
    return line;
  }
  if (chatter.order) {
    const line = chatter.order[state.index % chatter.order.length];
    state.index++;
    return line;
  }
  const { phrase } = weighted(chatter.units, random() * chatter.totalWeight);
  if (phrase.length > 1) {
    state.phrase = phrase;
    state.at = 1;
  }
  return phrase[0];
}

/** The option `roll` (0 to the options' total weight) lands on. */
function weighted(options, roll) {
  for (const option of options) {
    roll -= option.weight;
    if (roll < 0) return option;
  }
  return options[options.length - 1];
}

/** The animation and sound that go with a line: its own, or one of its alternating gestures. */
function gestureFor(line) {
  if (!line.gestures) return line;
  const total = line.gestures.reduce((sum, gesture) => sum + gesture.weight, 0);
  return weighted(line.gestures, random() * total);
}

function discover(now) {
  for (const npc of core.World.getActiveNpcsForUpdate()) {
    if (!npc || live.has(npc)) continue;
    const chatter = chatterById.get(npc.getId());
    if (!chatter) continue;
    live.add(npc);
    const index = chatter.order ? Math.floor(random() * chatter.order.length) : 0;
    schedule.set(npc, { next: now + Math.floor(random() * sampleGap(chatter.gap)) + 1, index });
  }
}

function isPlayer(mobile) {
  return mobile?.isPlayer?.() === true;
}

function isNpc(mobile) {
  return mobile?.isNpc?.() === true;
}

/** Whether the NPC is talking to or fighting a player, or dying. */
function busy(npc) {
  if (npc.isDyingFunction?.()) return true;
  const combat = npc.getCombat();
  return isPlayer(npc.getInteractingMobile()) || isPlayer(combat.getTarget()) || isPlayer(combat.getAttacker());
}

function fightingNpc(npc) {
  const combat = npc.getCombat();
  return isNpc(combat.getTarget()) || isNpc(combat.getAttacker());
}

function say(npc, line) {
  npc.forceChat(line.text);
  const gesture = gestureFor(line);
  if (gesture.seq != null) npc.performAnimation(new core.Animation(gesture.seq));
  if (gesture.sound) {
    const at = npc.getLocation();
    core.Sounds.playAreaSound({
      soundId: gesture.sound.id, x: at.getX(), y: at.getY(), level: at.getZ(), radius: gesture.sound.range, source: npc,
    });
  }
}

function tick(now) {
  if (now >= nextDiscover) {
    nextDiscover = now + DISCOVER_TICKS;
    discover(now);
  }
  for (const npc of live) {
    const chatter = chatterById.get(npc.getId());
    if (!chatter || !npc.isRegistered() || !core.World.isLocationActive(npc.getLocation())) {
      live.delete(npc);
      schedule.delete(npc);
      continue;
    }
    const state = schedule.get(npc);
    if (now < state.next) continue;
    if (busy(npc) || (chatter.fighting && !fightingNpc(npc))) {
      state.next = now + BUSY_RETRY_TICKS;
      continue;
    }
    say(npc, pickLine(chatter, state));
    state.next = now + sampleGap(state.phrase ? chatter.phraseGap : chatter.gap);
  }
}

function setRandom(fn) {
  random = fn ?? Math.random;
}

function reset() {
  live.clear();
  nextDiscover = 0;
}

module.exports = {
  name: "NpcChatter",
  description: "NPCs say their ambient overhead lines (ducks, sheep, GE experts, town criers, Goblin Village soldiers) with live timing.",
  register(pluginApi) {
    pluginApi.onServerStartup(() => start(pluginApi));
  },
  _test: { load, entryFor, sampleGap, pickLine, gestureFor, tick, discover, chatterById, live, schedule, setRandom, reset, readDefinitions,
    setCore: (c) => { core = c; } },
};
